-- REVISED PROPOSAL ONLY. Original source/index and production are unchanged.
-- Run standalone, outside a transaction, only after exact DDL/cost/backup approval.
-- Nested CASE: JSON string, length 1..64, ASCII digits only. Invalid values become NULL.
-- ASCII validation uses translate, not locale-dependent regex ranges. C collation preserves exact ID equality.
-- No truncation, hashing, cast-to-varchar, or collision-prone key substitution.
CREATE INDEX CONCURRENTLY messages_telegram_reaction_album
ON public.messages (business_id,conversation_id,((case when jsonb_typeof((case when jsonb_typeof(raw_payload->'message')='object' then raw_payload->'message' else raw_payload end)->'media_group_id')='string' then case when length((case when jsonb_typeof(raw_payload->'message')='object' then raw_payload->'message' else raw_payload end)->>'media_group_id') between 1 and 64 then case when length(translate((case when jsonb_typeof(raw_payload->'message')='object' then raw_payload->'message' else raw_payload end)->>'media_group_id','0123456789',''))=0 then (case when jsonb_typeof(raw_payload->'message')='object' then raw_payload->'message' else raw_payload end)->>'media_group_id' else null end else null end else null end) COLLATE pg_catalog."C"))
WHERE ((case when jsonb_typeof((case when jsonb_typeof(raw_payload->'message')='object' then raw_payload->'message' else raw_payload end)->'media_group_id')='string' then case when length((case when jsonb_typeof(raw_payload->'message')='object' then raw_payload->'message' else raw_payload end)->>'media_group_id') between 1 and 64 then case when length(translate((case when jsonb_typeof(raw_payload->'message')='object' then raw_payload->'message' else raw_payload end)->>'media_group_id','0123456789',''))=0 then (case when jsonb_typeof(raw_payload->'message')='object' then raw_payload->'message' else raw_payload end)->>'media_group_id' else null end else null end else null end) COLLATE pg_catalog."C") IS NOT NULL;
